B=data/outputs-recovery/preflight/preflight-3; .venv/bin/python - "$B" <<'EOF'
import json, sys
from pathlib import Path
b = Path(sys.argv[1])
h = [json.loads(l) for l in open(b / "harness.jsonl")]
inj = next(e for e in h if e["event"] == "injection" and e.get("position") == 3)
t0 = inj["t_inj"]
rows = []
for p in sorted((b / "events").glob("*.jsonl")):
    for l in open(p):
        try:
            e = json.loads(l)
        except ValueError:
            continue
        if e.get("job_id") == 3 or (e.get("event") in ("started", "sweep", "assigned", "revoked", "lost", "stopped") and abs(e["mono"] - t0) < 200):
            keep = {k: e.get(k) for k in ("attempt", "step", "name", "outcome", "returncode", "closed", "retryable", "error", "reason", "during", "why", "partitions", "terminated", "preserved") if e.get(k) is not None}
            if "error" in keep:
                keep["error"] = str(keep["error"])[:160]
            rows.append((e["mono"] - t0, p.stem, e["event"], keep))
for t, who, ev, keep in sorted(rows):
    if -60 < t < 200:
        print(f"{t:+7.1f} {who:16} {ev:14} {json.dumps(keep, default=str)[:230]}")
EOF

