.venv/bin/python - <<'EOF'
import json
from datetime import datetime
from pathlib import Path
root = Path("data/outputs-recovery/preflight")
peaks, secs = {}, {}
for b in ("preflight-2", "preflight-3"):
    for rec in (root / b).glob("**/logs/*.launcher.json"):
        if ".work" in rec.parts:
            continue
        r = json.loads(rec.read_text())
        step = rec.name.split(".")[0]
        if r.get("outcome") == "exited":
            peaks.setdefault(step, []).append(r.get("peak_rss_bytes") or 0)
            if r.get("step_seconds") is not None:
                secs.setdefault(step, []).append(r["step_seconds"])
for step in ("windows", "spark_pipeline", "verify"):
    p, s = peaks.get(step, []), secs.get(step, [])
    print(f"{step:15} n={len(p):2}  peak tree RSS {min(p)/2**30:.2f}-{max(p)/2**30:.2f} GiB  step {min(s):.1f}-{max(s):.1f} s")
for b in ("preflight-2", "preflight-3"):
    h = [json.loads(l) for l in open(root / b / "harness.jsonl")]
    s, e = h[0], next(x for x in h if x["event"] == "batch_ended")
    wall = datetime.fromisoformat(e["ts"]).timestamp() - datetime.fromisoformat(s["ts"]).timestamp()
    print(f"{b}: monotonic {(e['mono'] - s['mono'])/60:.1f} min, wall {wall/60:.1f} min")
EOF

